mutation.old:
if (e.modifiers !== (ride ? 8 : 0)) {
  add(ride ? 'shift-modifiers-wrong' : 'shift-unshifted-char-wrong', 'i=' + i + ' char=' + ch + ' modifiers=' + JSON.stringify(e.modifiers));
}

mutation.new:
if (!ride && e.modifiers !== 0) {
